-- 众筹1.0本地权限配置；只适用于已核对的 iam_test / tenant 0 / client crowdfunding。
-- 先备份；通过IAM持久化任务同步缓存；不修改用户角色或其他客户端。
SET NAMES utf8mb4;
START TRANSACTION;
CREATE TEMPORARY TABLE codex_v1_iam_guard(ok INT CHECK(ok=1));
DROP TEMPORARY TABLE codex_v1_iam_guard;
SET @root=(SELECT id FROM system_menu WHERE client_id='crowdfunding' AND component_name='crowdfunding' AND deleted=0 AND tenant_id=0 LIMIT 1);
UPDATE system_menu SET name='众筹1.0' WHERE id=@root AND client_id='crowdfunding';
UPDATE system_role SET name='众筹1.0-员工',data_scope=5,data_scope_dept_ids='[]' WHERE id=33 AND code='crowdfunding_employee' AND tenant_id=0 AND deleted=0;
DELETE r FROM system_role_api r JOIN system_api_resource a ON a.id=r.api_resource_id WHERE r.role_id=33 AND r.tenant_id=0 AND a.client_id='crowdfunding';
DELETE r FROM system_role_menu r JOIN system_menu m ON m.id=r.menu_id WHERE r.role_id=33 AND r.tenant_id=0 AND m.client_id='crowdfunding';
UPDATE system_role SET name='众筹1.0-项目管理员',data_scope=1,data_scope_dept_ids='[]' WHERE id=32 AND code='crowdfunding_admin' AND tenant_id=0 AND deleted=0;
DELETE r FROM system_role_api r JOIN system_api_resource a ON a.id=r.api_resource_id WHERE r.role_id=32 AND r.tenant_id=0 AND a.client_id='crowdfunding';
DELETE r FROM system_role_menu r JOIN system_menu m ON m.id=r.menu_id WHERE r.role_id=32 AND r.tenant_id=0 AND m.client_id='crowdfunding';
UPDATE system_role SET name='众筹1.0-财务',data_scope=1,data_scope_dept_ids='[]' WHERE id=34 AND code='crowdfunding_finance' AND tenant_id=0 AND deleted=0;
DELETE r FROM system_role_api r JOIN system_api_resource a ON a.id=r.api_resource_id WHERE r.role_id=34 AND r.tenant_id=0 AND a.client_id='crowdfunding';
DELETE r FROM system_role_menu r JOIN system_menu m ON m.id=r.menu_id WHERE r.role_id=34 AND r.tenant_id=0 AND m.client_id='crowdfunding';
UPDATE system_role SET name='众筹1.0-公司超级管理员',data_scope=1,data_scope_dept_ids='[]' WHERE id=35 AND code='crowdfunding_super_admin' AND tenant_id=0 AND deleted=0;
DELETE r FROM system_role_api r JOIN system_api_resource a ON a.id=r.api_resource_id WHERE r.role_id=35 AND r.tenant_id=0 AND a.client_id='crowdfunding';
DELETE r FROM system_role_menu r JOIN system_menu m ON m.id=r.menu_id WHERE r.role_id=35 AND r.tenant_id=0 AND m.client_id='crowdfunding';
SET @task_start=(SELECT COALESCE(MAX(id),0) FROM system_authorization_cache_task);
COMMIT;
SELECT @task_start;
