INSERT INTO codex_v1_iam_guard SELECT IF(DATABASE()='iam_test' AND EXISTS(SELECT 1 FROM system_role WHERE id=33 AND code='crowdfunding_employee' AND tenant_id=0 AND deleted=0) AND EXISTS(SELECT 1 FROM system_role WHERE id=32 AND code='crowdfunding_admin' AND tenant_id=0 AND deleted=0) AND EXISTS(SELECT 1 FROM system_role WHERE id=34 AND code='crowdfunding_finance' AND tenant_id=0 AND deleted=0) AND EXISTS(SELECT 1 FROM system_role WHERE id=35 AND code='crowdfunding_super_admin' AND tenant_id=0 AND deleted=0) AND EXISTS(SELECT 1 FROM system_menu WHERE client_id='crowdfunding' AND component_name='crowdfunding' AND tenant_id=0 AND deleted=0),1,0);
